        internal const string gwp_ai_det_audience_outsider_high_calculating = "{=gwp_ai_det_audience_outsider_high_calculating}Whatever gain you imagine in a burning village, set it against years of pursuit before you decide.";
        internal const string gwp_ai_det_audience_outsider_high_cautious = "{=gwp_ai_det_audience_outsider_high_cautious}If self-preservation matters to you, do not give them a reason to learn your name.";
        internal const string gwp_ai_det_audience_outsider_high_closefisted = "{=gwp_ai_det_audience_outsider_high_closefisted}Even the most selfish arithmetic reaches the same answer: a raid is not worth what they collect afterward.";
        internal const string gwp_ai_det_audience_outsider_high_cruel = "{=gwp_ai_det_audience_outsider_high_cruel}Burn what you like, but understand that the Grey Wardens know how to make memory outlive pride.";
        internal const string gwp_ai_det_audience_outsider_high_dishonorable = "{=gwp_ai_det_audience_outsider_high_dishonorable}Choose carefully which laws you break. The Grey Wardens care more about the deed than the excuse.";
        internal const string gwp_ai_det_audience_outsider_high_generous = "{=gwp_ai_det_audience_outsider_high_generous}Think of your clan and followers before you make them inherit the price of your decision.";
        internal const string gwp_ai_det_audience_outsider_high_honorable = "{=gwp_ai_det_audience_outsider_high_honorable}I tell you plainly: protect the villages under your power, or justice will eventually find you as well.";
        internal const string gwp_ai_det_audience_outsider_high_impulsive = "{=gwp_ai_det_audience_outsider_high_impulsive}If your temper commands you, the Grey Wardens may be the ones who decide when it stops.";
        internal const string gwp_ai_det_audience_outsider_high_merciful = "{=gwp_ai_det_audience_outsider_high_merciful}Spare yourself this lesson by sparing the people who would otherwise suffer first.";
        internal const string gwp_ai_det_audience_outsider_high_neutral = "{=gwp_ai_det_audience_outsider_high_neutral}Stay away from that path unless you are prepared for the Grey Wardens to follow it back to you.";
        internal const string gwp_ai_det_audience_outsider_high_valorous = "{=gwp_ai_det_audience_outsider_high_valorous}If you want a worthy enemy, seek one who can fight back; the Grey Wardens will answer if you choose the helpless.";
        internal const string gwp_ai_det_audience_outsider_low_calculating = "{=gwp_ai_det_audience_outsider_low_calculating}If profit is what guides you, remember to include the Grey Wardens in your reckoning.";
        internal const string gwp_ai_det_audience_outsider_low_cautious = "{=gwp_ai_det_audience_outsider_low_cautious}You need not prove anything by provoking people who will pursue you without tiring.";
        internal const string gwp_ai_det_audience_outsider_low_closefisted = "{=gwp_ai_det_audience_outsider_low_closefisted}If conscience does not move you, then protect your own purse and soldiers.";
        internal const string gwp_ai_det_audience_outsider_low_cruel = "{=gwp_ai_det_audience_outsider_low_cruel}Do as you please, but do not say no one warned you what follows.";
        internal const string gwp_ai_det_audience_outsider_low_dishonorable = "{=gwp_ai_det_audience_outsider_low_dishonorable}Keep your promises if it suits you, but at least do not make yourself such easy prey.";
        internal const string gwp_ai_det_audience_outsider_low_generous = "{=gwp_ai_det_audience_outsider_low_generous}Do not make your followers and family pay for a choice made only to satisfy you.";
        internal const string gwp_ai_det_audience_outsider_low_honorable = "{=gwp_ai_det_audience_outsider_low_honorable}Take it as honest advice: do not bring the same judgment on yourself by preying on villages.";
        internal const string gwp_ai_det_audience_outsider_low_impulsive = "{=gwp_ai_det_audience_outsider_low_impulsive}Do not let one angry moment choose a road that takes years to escape.";
        internal const string gwp_ai_det_audience_outsider_low_merciful = "{=gwp_ai_det_audience_outsider_low_merciful}You can choose a better road before frightened families are made to pay for it.";
        internal const string gwp_ai_det_audience_outsider_low_neutral = "{=gwp_ai_det_audience_outsider_low_neutral}You would be wise to remember that before choosing your own targets.";
        internal const string gwp_ai_det_audience_outsider_low_valorous = "{=gwp_ai_det_audience_outsider_low_valorous}Test your courage on armed warriors, not on villagers who cannot answer you.";
        internal const string gwp_ai_det_audience_outsider_medium_calculating = "{=gwp_ai_det_audience_outsider_medium_calculating}If you intend to raid, understand that the cost may follow you long after the loot is spent.";
        internal const string gwp_ai_det_audience_outsider_medium_cautious = "{=gwp_ai_det_audience_outsider_medium_cautious}Turn away from the villages while the choice is still yours; retreat is cheaper before pursuit begins.";
        internal const string gwp_ai_det_audience_outsider_medium_closefisted = "{=gwp_ai_det_audience_outsider_medium_closefisted}The loot from a village will not repay the men, coin, and freedom that pursuit can cost.";
        internal const string gwp_ai_det_audience_outsider_medium_cruel = "{=gwp_ai_det_audience_outsider_medium_cruel}Choose that road if you wish. Just be ready to pay more than you take.";
        internal const string gwp_ai_det_audience_outsider_medium_dishonorable = "{=gwp_ai_det_audience_outsider_medium_dishonorable}If you cross that line, do not imagine that rank or a convenient excuse will shield you.";
        internal const string gwp_ai_det_audience_outsider_medium_generous = "{=gwp_ai_det_audience_outsider_medium_generous}A lord owes protection to those who trust them, not a trail of losses created for pride.";
        internal const string gwp_ai_det_audience_outsider_medium_honorable = "{=gwp_ai_det_audience_outsider_medium_honorable}Keep faith with the innocent, and you will never need to learn that lesson as I did.";
        internal const string gwp_ai_det_audience_outsider_medium_impulsive = "{=gwp_ai_det_audience_outsider_medium_impulsive}Pause before you order the torches lit. Anger leaves faster than consequences.";
        internal const string gwp_ai_det_audience_outsider_medium_merciful = "{=gwp_ai_det_audience_outsider_medium_merciful}Leave the villages in peace; their people have already endured enough from lords like us.";
        internal const string gwp_ai_det_audience_outsider_medium_neutral = "{=gwp_ai_det_audience_outsider_medium_neutral}Consider the consequence before you make the same choice.";
        internal const string gwp_ai_det_audience_outsider_medium_valorous = "{=gwp_ai_det_audience_outsider_medium_valorous}Do not mistake cruelty toward the helpless for bravery, nor the Grey Wardens' patience for weakness.";
        internal const string gwp_ai_det_audience_warden_high_calculating = "{=gwp_ai_det_audience_warden_high_calculating}Because you work with them, you should understand this: fear spends quickly, but consistent law keeps paying.";
        internal const string gwp_ai_det_audience_warden_high_cautious = "{=gwp_ai_det_audience_warden_high_cautious}If the Grey Wardens send you after dangerous people, remember that caution keeps an enforcer alive.";
        internal const string gwp_ai_det_audience_warden_high_closefisted = "{=gwp_ai_det_audience_warden_high_closefisted}If you serve only for profit, understand that uncontrolled enforcement eventually costs more than it pays.";
        internal const string gwp_ai_det_audience_warden_high_cruel = "{=gwp_ai_det_audience_warden_high_cruel}Their mark is on my house, and you have chosen their side. Do not expect me to confuse either with friendship.";
        internal const string gwp_ai_det_audience_warden_high_dishonorable = "{=gwp_ai_det_audience_warden_high_dishonorable}If you call what you do justice, prove it through consistent conduct rather than the power to punish.";
        internal const string gwp_ai_det_audience_warden_high_generous = "{=gwp_ai_det_audience_warden_high_generous}Their authority makes you responsible for everyone placed in danger by your decisions.";
        internal const string gwp_ai_det_audience_warden_high_honorable = "{=gwp_ai_det_audience_warden_high_honorable}You represent them now. If their justice is to mean anything, your conduct must be cleaner than the crimes you pursue.";
        internal const string gwp_ai_det_audience_warden_high_impulsive = "{=gwp_ai_det_audience_warden_high_impulsive}If temper governs your sword, their authority will not stop you from becoming another danger to the innocent.";
        internal const string gwp_ai_det_audience_warden_high_merciful = "{=gwp_ai_det_audience_warden_high_merciful}Stand between the Grey Wardens and needless suffering when you can; justice has no need to become cruelty.";
        internal const string gwp_ai_det_audience_warden_high_neutral = "{=gwp_ai_det_audience_warden_high_neutral}You chose to work with the Grey Wardens. Then you should know that what they do is remembered long after the warrant closes.";
        internal const string gwp_ai_det_audience_warden_high_valorous = "{=gwp_ai_det_audience_warden_high_valorous}Stand with them boldly if you must, but let your courage be measured by whom you protect, not whom you can frighten.";
        internal const string gwp_ai_det_audience_warden_low_calculating = "{=gwp_ai_det_audience_warden_low_calculating}You chose to work with the Grey Wardens; that makes candour more useful than pretence.";
        internal const string gwp_ai_det_audience_warden_low_cautious = "{=gwp_ai_det_audience_warden_low_cautious}Authority can make a fool reckless. Do not let their name push you into a fight you have not measured.";
        internal const string gwp_ai_det_audience_warden_low_closefisted = "{=gwp_ai_det_audience_warden_low_closefisted}If a bounty pays you, do not pretend that coin and justice are the same thing.";
        internal const string gwp_ai_det_audience_warden_low_cruel = "{=gwp_ai_det_audience_warden_low_cruel}So you chose to work with them. Do not expect that alone to make every lord bow.";
        internal const string gwp_ai_det_audience_warden_low_dishonorable = "{=gwp_ai_det_audience_warden_low_dishonorable}You carry their warrants, but ink alone does not turn power into virtue.";
        internal const string gwp_ai_det_audience_warden_low_generous = "{=gwp_ai_det_audience_warden_low_generous}If you serve them, remember the people who follow you and will pay for every order.";
        internal const string gwp_ai_det_audience_warden_low_honorable = "{=gwp_ai_det_audience_warden_low_honorable}Since you serve beside them, hold yourself to the same law they claimed to uphold when they intervened.";
        internal const string gwp_ai_det_audience_warden_low_impulsive = "{=gwp_ai_det_audience_warden_low_impulsive}A warrant does not excuse acting in anger. You are still answerable for what follows.";
        internal const string gwp_ai_det_audience_warden_low_merciful = "{=gwp_ai_det_audience_warden_low_merciful}If you work with them, use that place to protect villagers before punishment becomes necessary.";
        internal const string gwp_ai_det_audience_warden_low_neutral = "{=gwp_ai_det_audience_warden_low_neutral}You serve with the Grey Wardens, so you should understand why the matter is remembered.";
        internal const string gwp_ai_det_audience_warden_low_valorous = "{=gwp_ai_det_audience_warden_low_valorous}You carry their authority now; prove that it rests on courage rather than intimidation.";
        internal const string gwp_ai_det_audience_warden_medium_calculating = "{=gwp_ai_det_audience_warden_medium_calculating}A Grey Warden ally should know that measured enforcement wins more obedience than needless humiliation.";
        internal const string gwp_ai_det_audience_warden_medium_cautious = "{=gwp_ai_det_audience_warden_medium_cautious}A warrant is no substitute for knowing when to advance and when to withdraw.";
        internal const string gwp_ai_det_audience_warden_medium_closefisted = "{=gwp_ai_det_audience_warden_medium_closefisted}Do not spend other people's lives merely to enlarge your reward.";
        internal const string gwp_ai_det_audience_warden_medium_cruel = "{=gwp_ai_det_audience_warden_medium_cruel}You may hunt for them, but do not mistake a warrant for invincibility.";
        internal const string gwp_ai_det_audience_warden_medium_dishonorable = "{=gwp_ai_det_audience_warden_medium_dishonorable}Use their authority if you must, but do not preach purity while bending the law for yourself.";
        internal const string gwp_ai_det_audience_warden_medium_generous = "{=gwp_ai_det_audience_warden_medium_generous}Protect your companions and the villagers alike; authority is a debt before it is a privilege.";
        internal const string gwp_ai_det_audience_warden_medium_honorable = "{=gwp_ai_det_audience_warden_medium_honorable}If you act in their name, keep the law above vengeance, even when the accused deserves no sympathy.";
        internal const string gwp_ai_det_audience_warden_medium_impulsive = "{=gwp_ai_det_audience_warden_medium_impulsive}Do not let an insult turn enforcement into vengeance simply because their seal is behind you.";
        internal const string gwp_ai_det_audience_warden_medium_merciful = "{=gwp_ai_det_audience_warden_medium_merciful}Use your place among them to prevent the next village from suffering, not merely to punish afterward.";
        internal const string gwp_ai_det_audience_warden_medium_neutral = "{=gwp_ai_det_audience_warden_medium_neutral}You know their methods from the other side of the warrant; remember what those methods leave behind.";
        internal const string gwp_ai_det_audience_warden_medium_valorous = "{=gwp_ai_det_audience_warden_medium_valorous}If you bear their authority, meet armed offenders openly and leave terror to lesser people.";
        internal const string gwp_ai_det_core_family_high_calculating = "{=gwp_ai_det_core_family_high_calculating}No one in my clan now discusses a village raid without first accounting for the Grey Wardens' answer.";
        internal const string gwp_ai_det_core_family_high_cautious = "{=gwp_ai_det_core_family_high_cautious}We know how completely they can close around a clan. Avoiding that danger again is survival, not submission.";
        internal const string gwp_ai_det_core_family_high_closefisted = "{=gwp_ai_det_core_family_high_closefisted}The Grey Wardens taught us that one relative's folly can become everyone's expense. I will not permit that twice.";
        internal const string gwp_ai_det_core_family_high_cruel = "{=gwp_ai_det_core_family_high_cruel}Their hand still lies heavy on my clan. We have not submitted; we have merely learned when vengeance is too costly.";
        internal const string gwp_ai_det_core_family_high_dishonorable = "{=gwp_ai_det_core_family_high_dishonorable}My clan remembers the punishment as an insult, not a judgment. Restraint does not mean that we accept their right.";
        internal const string gwp_ai_det_core_family_high_generous = "{=gwp_ai_det_core_family_high_generous}The whole clan carried the burden. I owe protection to those who kept faith when another brought ruin home.";
        internal const string gwp_ai_det_core_family_high_honorable = "{=gwp_ai_det_core_family_high_honorable}The lesson reached the whole clan: rank and blood do not excuse a crime against those under our protection.";
        internal const string gwp_ai_det_core_family_high_impulsive = "{=gwp_ai_det_core_family_high_impulsive}The whole clan felt the consequence of one unchecked impulse. Now even anger must answer to that memory.";
        internal const string gwp_ai_det_core_family_high_merciful = "{=gwp_ai_det_core_family_high_merciful}If my kin finally understand the suffering they caused, then perhaps something decent can still come from the punishment.";
        internal const string gwp_ai_det_core_family_high_neutral = "{=gwp_ai_det_core_family_high_neutral}The consequences settled over the entire clan. None of us now treats the Grey Wardens as a distant concern.";
        internal const string gwp_ai_det_core_family_high_valorous = "{=gwp_ai_det_core_family_high_valorous}My house still has courage, but courage now walks beside a very clear memory of the Grey Wardens.";
        internal const string gwp_ai_det_core_family_low_calculating = "{=gwp_ai_det_core_family_low_calculating}What happened to my kin gave the clan a useful measure of the risks involved.";
        internal const string gwp_ai_det_core_family_low_cautious = "{=gwp_ai_det_core_family_low_cautious}What happened to my kin showed us a danger the clan would be foolish to provoke without need.";
        internal const string gwp_ai_det_core_family_low_closefisted = "{=gwp_ai_det_core_family_low_closefisted}My kinsman's folly became a bill for the whole clan. They should have borne it alone.";
        internal const string gwp_ai_det_core_family_low_cruel = "{=gwp_ai_det_core_family_low_cruel}They laid hands on my blood. I remember it, even while I let the matter rest.";
        internal const string gwp_ai_det_core_family_low_dishonorable = "{=gwp_ai_det_core_family_low_dishonorable}Blood comes before strangers' rules. I judge the Grey Wardens by what they did to my kin, not by the charge they named.";
        internal const string gwp_ai_det_core_family_low_generous = "{=gwp_ai_det_core_family_low_generous}Whatever my kinsman's fault, they are still ours. We must correct them without abandoning them.";
        internal const string gwp_ai_det_core_family_low_honorable = "{=gwp_ai_det_core_family_low_honorable}My kin crossed a boundary. I cannot call the Grey Wardens wrong for answering it.";
        internal const string gwp_ai_det_core_family_low_impulsive = "{=gwp_ai_det_core_family_low_impulsive}My kin acted before thinking, and the rest of us were left to remember the result.";
        internal const string gwp_ai_det_core_family_low_merciful = "{=gwp_ai_det_core_family_low_merciful}I am more troubled by the villagers who suffered than by my kin's wounded pride.";
        internal const string gwp_ai_det_core_family_low_neutral = "{=gwp_ai_det_core_family_low_neutral}The affair touched my family, so naturally the clan remembers it.";
        internal const string gwp_ai_det_core_family_low_valorous = "{=gwp_ai_det_core_family_low_valorous}My clan took a blow; it did not lose its courage. Still, the warning was clear.";
        internal const string gwp_ai_det_core_family_medium_calculating = "{=gwp_ai_det_core_family_medium_calculating}The clan has counted the men, coin, and freedom that one reckless choice cost us.";
        internal const string gwp_ai_det_core_family_medium_cautious = "{=gwp_ai_det_core_family_medium_cautious}The clan has no desire to walk into the same trap merely to prove that it is unafraid.";
        internal const string gwp_ai_det_core_family_medium_closefisted = "{=gwp_ai_det_core_family_medium_closefisted}I have no intention of paying again for a relative's appetite for plunder.";
        internal const string gwp_ai_det_core_family_medium_cruel = "{=gwp_ai_det_core_family_medium_cruel}The Grey Wardens made my clan bleed for another's mistake. Such accounts are not forgotten.";
        internal const string gwp_ai_det_core_family_medium_dishonorable = "{=gwp_ai_det_core_family_medium_dishonorable}Whatever my kinsman did, outsiders had no right to humble our house and call the matter justice.";
        internal const string gwp_ai_det_core_family_medium_generous = "{=gwp_ai_det_core_family_medium_generous}One kinsman's mistake cost everyone who stood beside them. Our duty now is to repair what it damaged.";
        internal const string gwp_ai_det_core_family_medium_honorable = "{=gwp_ai_det_core_family_medium_honorable}My kinsman broke the peace and the clan paid for it. Responsibility does not vanish merely because blood is shared.";
        internal const string gwp_ai_det_core_family_medium_impulsive = "{=gwp_ai_det_core_family_medium_impulsive}One hotheaded decision brought the Grey Wardens down on all of us. That is not easily forgotten.";
        internal const string gwp_ai_det_core_family_medium_merciful = "{=gwp_ai_det_core_family_medium_merciful}I would rather my family learn restraint than leave more peasants grieving for what nobles chose to do.";
        internal const string gwp_ai_det_core_family_medium_neutral = "{=gwp_ai_det_core_family_medium_neutral}What happened to one of us changed how the whole clan speaks of raids and reprisals.";
        internal const string gwp_ai_det_core_family_medium_valorous = "{=gwp_ai_det_core_family_medium_valorous}We are not cowed, but neither will we charge blindly into the same punishment twice.";
        internal const string gwp_ai_det_core_personal_high_calculating = "{=gwp_ai_det_core_personal_high_calculating}Now every road toward a village includes the same figure in my reckoning: what the Grey Wardens will take in return.";
        internal const string gwp_ai_det_core_personal_high_cautious = "{=gwp_ai_det_core_personal_high_cautious}I survived by learning which fights to avoid. Giving them another reason to pursue me would be needless folly.";
        internal const string gwp_ai_det_core_personal_high_closefisted = "{=gwp_ai_det_core_personal_high_closefisted}I will not impoverish myself for plunder that the Grey Wardens can take back with interest.";
        internal const string gwp_ai_det_core_personal_high_cruel = "{=gwp_ai_det_core_personal_high_cruel}I remember exactly what they did. My restraint is calculation, not surrender and certainly not forgiveness.";
        internal const string gwp_ai_det_core_personal_high_dishonorable = "{=gwp_ai_det_core_personal_high_dishonorable}I regret being caught, not crossing their line. What changed is that I now hide my steps more carefully.";
        internal const string gwp_ai_det_core_personal_high_generous = "{=gwp_ai_det_core_personal_high_generous}I cannot ask my household to endure that cost again merely to satisfy one more raid.";
        internal const string gwp_ai_det_core_personal_high_honorable = "{=gwp_ai_det_core_personal_high_honorable}I was guilty, and the punishment was deserved. The depth of the lesson does not make the judgment less just.";
        internal const string gwp_ai_det_core_personal_high_impulsive = "{=gwp_ai_det_core_personal_high_impulsive}Whenever my temper rises, the memory of that punishment drags it down before I act.";
        internal const string gwp_ai_det_core_personal_high_merciful = "{=gwp_ai_det_core_personal_high_merciful}What weighs on me most is not what they did to me, but what my choices had already done to people who could not resist.";
        internal const string gwp_ai_det_core_personal_high_neutral = "{=gwp_ai_det_core_personal_high_neutral}Their intervention changed how I judge every raid, every captive, and every road back home.";
        internal const string gwp_ai_det_core_personal_high_valorous = "{=gwp_ai_det_core_personal_high_valorous}I could face them again. That does not mean I am foolish enough to call them harmless.";
        internal const string gwp_ai_det_core_personal_low_calculating = "{=gwp_ai_det_core_personal_low_calculating}That affair taught me where the cost begins to outweigh the gain.";
        internal const string gwp_ai_det_core_personal_low_cautious = "{=gwp_ai_det_core_personal_low_cautious}I have no wish to face the Grey Wardens again over something as small as a village raid.";
        internal const string gwp_ai_det_core_personal_low_closefisted = "{=gwp_ai_det_core_personal_low_closefisted}I lost more than I gained. I will not waste my own men and coin that way again.";
        internal const string gwp_ai_det_core_personal_low_cruel = "{=gwp_ai_det_core_personal_low_cruel}They made their point. I have simply chosen not to test it again yet.";
        internal const string gwp_ai_det_core_personal_low_dishonorable = "{=gwp_ai_det_core_personal_low_dishonorable}Rules are useful until they obstruct necessity. Being caught only proved that I chose the wrong moment.";
        internal const string gwp_ai_det_core_personal_low_generous = "{=gwp_ai_det_core_personal_low_generous}My followers paid for my choice as surely as I did. I owe them better judgment next time.";
        internal const string gwp_ai_det_core_personal_low_honorable = "{=gwp_ai_det_core_personal_low_honorable}I crossed a boundary, and being stopped was the proper consequence.";
        internal const string gwp_ai_det_core_personal_low_impulsive = "{=gwp_ai_det_core_personal_low_impulsive}I acted in anger and paid for it before the anger had even cooled.";
        internal const string gwp_ai_det_core_personal_low_merciful = "{=gwp_ai_det_core_personal_low_merciful}Whatever my reasons, villagers should not have borne the price.";
        internal const string gwp_ai_det_core_personal_low_neutral = "{=gwp_ai_det_core_personal_low_neutral}The matter is over, but I have not discarded its lesson.";
        internal const string gwp_ai_det_core_personal_low_valorous = "{=gwp_ai_det_core_personal_low_valorous}One defeat does not make me afraid, but it taught me to respect the Grey Wardens' reach.";
        internal const string gwp_ai_det_core_personal_medium_calculating = "{=gwp_ai_det_core_personal_medium_calculating}I have measured the losses twice. No village is worth drawing that pursuit without a far greater purpose.";
        internal const string gwp_ai_det_core_personal_medium_cautious = "{=gwp_ai_det_core_personal_medium_cautious}Call it caution if you like. I know how quickly they can close every road around a person.";
        internal const string gwp_ai_det_core_personal_medium_closefisted = "{=gwp_ai_det_core_personal_medium_closefisted}A burned village is not worth my soldiers, my coin, and my freedom all at once.";
        internal const string gwp_ai_det_core_personal_medium_cruel = "{=gwp_ai_det_core_personal_medium_cruel}They hurt me enough to make patience useful. Do not confuse that with remorse.";
        internal const string gwp_ai_det_core_personal_medium_dishonorable = "{=gwp_ai_det_core_personal_medium_dishonorable}I will not pretend their law was sacred. I learned only that breaking it openly gives enemies a weapon.";
        internal const string gwp_ai_det_core_personal_medium_generous = "{=gwp_ai_det_core_personal_medium_generous}The people who followed me bore the losses of my decision. Loyalty requires that I not spend them so carelessly again.";
        internal const string gwp_ai_det_core_personal_medium_honorable = "{=gwp_ai_det_core_personal_medium_honorable}I broke the peace and answered for it. Denying that would only add cowardice to the fault.";
        internal const string gwp_ai_det_core_personal_medium_impulsive = "{=gwp_ai_det_core_personal_medium_impulsive}I let anger choose the road, and the Grey Wardens decided where that road ended.";
        internal const string gwp_ai_det_core_personal_medium_merciful = "{=gwp_ai_det_core_personal_medium_merciful}I remember the frightened villagers more clearly than the chains. That is reason enough to stop.";
        internal const string gwp_ai_det_core_personal_medium_neutral = "{=gwp_ai_det_core_personal_medium_neutral}Since that capture, every raid carries a second calculation: whether the Grey Wardens will answer.";
        internal const string gwp_ai_det_core_personal_medium_valorous = "{=gwp_ai_det_core_personal_medium_valorous}I do not fear a hard fight, but only a fool mistakes courage for blindness to consequence.";
        internal const string gwp_ai_det_intro_family_high = "{=gwp_ai_det_intro_family_high}{HERO_NAME}'s expression hardens for a moment. The Grey Wardens' actions still hang heavily over their clan.";
        internal const string gwp_ai_det_intro_family_low = "{=gwp_ai_det_intro_family_low}{HERO_NAME} pauses briefly before speaking. The Grey Wardens' dealings with their kin have not quite been forgotten.";
        internal const string gwp_ai_det_intro_family_medium = "{=gwp_ai_det_intro_family_medium}{HERO_NAME} chooses each word carefully. Their clan's encounter with the Grey Wardens remains a serious concern.";
        internal const string gwp_ai_det_intro_personal_high = "{=gwp_ai_det_intro_personal_high}{HERO_NAME} holds your gaze with deliberate composure. What the Grey Wardens did to them left a mark too deep to conceal.";
        internal const string gwp_ai_det_intro_personal_low = "{=gwp_ai_det_intro_personal_low}{HERO_NAME} regards you steadily. Their encounter with the Grey Wardens is remembered, but it does not rule their manner.";
        internal const string gwp_ai_det_intro_personal_medium = "{=gwp_ai_det_intro_personal_medium}{HERO_NAME}'s voice grows more measured. Their own encounter with the Grey Wardens still weighs on every word.";
        internal const string gwp_asset_gold = "{=gwp_asset_gold}Gold";
        internal const string gwp_asset_value = "{=gwp_asset_value}{VAR_1} ({VAR_2} denars each)";
        internal const string gwp_atonement_closed_elsewhere = "{=gwp_atonement_closed_elsewhere}This case has been settled by someone else. Your atonement assignment is withdrawn, and you will not be penalized.";
        internal const string gwp_atonement_report = "{=gwp_atonement_report}Tell us how the case ended, and hand over anything you collected on our behalf.";
        internal const string gwp_battle_support_enemy = "{=gwp_battle_support_enemy}Grey Warden reinforcements have joined the enemy!";
        internal const string gwp_bio_hint_caravan = "{=gwp_bio_hint_caravan}She patrols the trade roads and pursues those who attack caravans.";
        internal const string gwp_bio_hint_issues = "{=gwp_bio_hint_issues}She travels between villages and towns to hear the notables' petitions.";
        internal const string gwp_bio_hint_law = "{=gwp_bio_hint_law}She serves with the patrols, dealing with cases across the land.";
        internal const string gwp_bio_hint_player = "{=gwp_bio_hint_player}She receives appeals from nobles and seeks a public decision for Wardens who have suffered injustice.";
        internal const string gwp_bio_hint_rebuild = "{=gwp_bio_hint_rebuild}She oversees rebuilding in ruined villages and helps their scattered people return.";
        internal const string gwp_bio_hint_training = "{=gwp_bio_hint_training}She trains the soldiers, teaching new recruits to hold their ranks.";
        internal const string gwp_bio_hint_village = "{=gwp_bio_hint_village}She pursues village raiders and protects villagers on the roads.";
