        internal const string gwp_bounty_contract_timed_out = "{=gwp_bounty_contract_timed_out}The bounty has expired. The hunt is over.";
        internal const string gwp_bounty_contract_timed_out_log = "{=gwp_bounty_contract_timed_out_log}The bounty contract expired before the quarry was defeated.";
