        internal const string gwp_bounty_duty_requirements = "{=gwp_bounty_duty_requirements}Equip the duty banner and reach {STANDING} standing.";
        internal const string gwp_bounty_intel_lost = "{=gwp_bounty_intel_lost}[Investigation] The scouts have lost the trail. There is no sighting to report this time.";
        internal const string gwp_bounty_intel_sheltered = "{=gwp_bounty_intel_sheltered}[Investigation] The target still leads no party and is staying in the lord's hall of {VAR_1}.";
        internal const string gwp_bounty_membership_ended = "{=gwp_bounty_membership_ended}You left the Grey Wardens, and the active bounty contract was withdrawn.";
        internal const string gwp_bounty_quest_reward = "{=gwp_bounty_quest_reward}Within 45 days, resolve the case by negotiation, defeat the offender's party, or capture the offender. The assessed fine is {VAR_1} denars. Report to a Grey Warden lord and hand over any fines collected or the captive. The case fee is assessed separately from the money collected; a delivered captive is also bought at the ransom price.";
