        internal const string gwp_case_closed_elsewhere = "{=gwp_case_closed_elsewhere}Your commission concerning {VAR_1} has been withdrawn. Report to a Grey Warden lord in person or send a messenger.";
        internal const string gwp_case_collect_amount = "{=gwp_case_collect_amount}Present property worth {VAR_1} denars. I will report the payment and any shortfall.";
        internal const string gwp_case_custody_buy = "{=gwp_case_custody_buy}Let us discuss the ransom.";
        internal const string gwp_case_custody_declined = "{=gwp_case_custody_declined}We have no agreement.";
