        internal const string gwp_case_custody_help = "{=gwp_case_custody_help}Negotiate a transfer with the captor, or withdraw the commission.";
        internal const string gwp_case_custody_leave = "{=gwp_case_custody_leave}Perhaps another time.";
        internal const string gwp_case_custody_offer = "{=gwp_case_custody_offer}We can discuss a price for the prisoner.";
        internal const string gwp_case_custody_request = "{=gwp_case_custody_request}Your prisoner {NAME} is the subject of my commission. I wish to take custody.";
        internal const string gwp_case_custody_withdraw = "{=gwp_case_custody_withdraw}Withdraw commission";
        internal const string gwp_case_custody_withdraw_prompt = "{=gwp_case_custody_withdraw_prompt}The target is captive, in hiding, or waiting to form a new party. Withdraw this commission without penalty and return the unresolved case to the pool?";
        internal const string gwp_case_custody_withdrawn = "{=gwp_case_custody_withdrawn}The commission has been withdrawn. The offender remains wanted.";
