        internal const string gwp_dispatch_word_truth = "{=gwp_dispatch_word_truth}Tell the truth";
        internal const string gwp_duel_collect_later = "{=gwp_duel_collect_later}I will collect it later.";
        internal const string gwp_duel_inspect_property = "{=gwp_duel_inspect_property}Show me your property. We will settle the fine now.";
        internal const string gwp_duel_payment_pending = "{=gwp_duel_payment_pending}You win the duel. You may now collect his fine.";
        internal const string gwp_duel_return_collect = "{=gwp_duel_return_collect}You won our duel. I still owe you the payment we agreed.";
        internal const string gwp_duty_banner_issued = "{=gwp_duty_banner_issued}Here is your standard. Equip it to serve under the Grey Wardens’ black and gold bird emblem and receive new warrants; keep it in your baggage when off duty. Return it when you leave the order.";
        internal const string gwp_duty_banner_request = "{=gwp_duty_banner_request}I need a replacement duty standard.";
        internal const string gwp_duty_caravan = "{=gwp_duty_caravan}Caravan Protection Warden";
        internal const string gwp_duty_issues = "{=gwp_duty_issues}Petition Warden";
        internal const string gwp_duty_player = "{=gwp_duty_player}Noble Affairs Liaison";
        internal const string gwp_duty_training = "{=gwp_duty_training}Training Warden";
        internal const string gwp_duty_village = "{=gwp_duty_village}Village Protection Warden";
        internal const string gwp_enc_chenxi = "{=gwp_enc_chenxi}{HERO_NAME} oversees the rebuilding of villages after war. When the pursuit has moved on, she often remains to arrange repairs, clear wells, and help scattered families return. She regards this work as a duty of faith, as necessary as pursuing the raiders. She is warm and willing to share the work herself, and is good at putting a tangled situation in order one task at a time.";
        internal const string gwp_enc_mise = "{=gwp_enc_mise}{HERO_NAME} pursues those who attack villages. She remembers the names of many burned settlements and knows the paths their people take when fleeing. News of a raid sends her gathering riders; she holds that no one's faith can excuse their being robbed or killed. She rarely raises her voice and listens patiently to those who have suffered. Before a fight, she arranges shelter for the old and the young.";
        internal const string gwp_enc_muguang = "{=gwp_enc_muguang}{HERO_NAME} receives appeals from nobles for the order, with particular concern for wrongs done to its members. She first hears what happened, then brings those concerned before a public decision. When precedent offers no answer, she takes the matter back to the order for discussion. She speaks gently and considers a promise before making it. Once committed, she patiently sees the matter through.";
        internal const string gwp_enc_shengduo = "{=gwp_enc_shengduo}{HERO_NAME} hears petitions for the order. Village headmen, merchants, and artisans bring disputes before her, and she enters the alleys to question those unwilling to approach an official. She carries old Imperial statutes to help establish the facts, then mediates under the order's rule. She is quick-witted and often eases an argument with a joke, then asks careful questions when accounts disagree.";
        internal const string gwp_enc_vandi = "{=gwp_enc_vandi}{HERO_NAME} is the present Warden-General and oversees the training of the order's soldiers. Before dawn she often inspects recruits and has veterans close the gaps in their shield wall. She believes Heaven has charged the Wardens with protecting the common folk, and forbids them to use the order to pursue crowns or enlarge private estates. She speaks plainly and sets clear expectations. When danger comes, she expects to take the first risk herself.";
        internal const string gwp_enc_yoer = "{=gwp_enc_yoer}{HERO_NAME} protects the trade roads, riding between bridges, ferries, and markets. She pursues attacks on caravans and unlawful tolls, refusing to dismiss them as ordinary wartime losses. Many who trade along these roads know her grey mantle. She is cheerful and enjoys talking with her escorts on the march. Once she has promised to keep a road safe, she is slow to abandon it.";
        internal const string gwp_enforcement_companion_charge = "{=gwp_enforcement_companion_charge}Stand! {VAR_1} travels with you under a Grey Warden warrant. The fine for {VAR_1}'s case is {VAR_2} denars. {VAR_3}";
        internal const string gwp_enforcement_companion_insufficient = "{=gwp_enforcement_companion_insufficient}You carry {VAR_1} denars. Return when you can pay the fine in full.";
        internal const string gwp_enforcement_companion_leave = "{=gwp_enforcement_companion_leave}I cannot settle this companion's case now.";
        internal const string gwp_enforcement_companion_paid = "{=gwp_enforcement_companion_paid}{VAR_1} has paid the fine of {VAR_2} denars. The case is closed.";
        internal const string gwp_enforcement_companion_pay = "{=gwp_enforcement_companion_pay}Pay this companion's fine ({VAR_1} denars)";
        internal const string gwp_envoy_duel_called = "{=gwp_envoy_duel_called}{VAR_1} has challenged {VAR_2} to settle the Wardens' charge at the tournament in {VAR_3}.";
        internal const string gwp_envoy_duel_moved = "{=gwp_envoy_duel_moved}The duel between {VAR_1} and {VAR_2} moves to the tournament in {VAR_3}.";
        internal const string gwp_envoy_duel_offender_won = "{=gwp_envoy_duel_offender_won}{VAR_1} placed above {VAR_2} at the tournament in {VAR_3}, and the Wardens let him go as agreed.";
        internal const string gwp_envoy_duel_warden_won = "{=gwp_envoy_duel_warden_won}{VAR_1} placed above {VAR_2} at the tournament in {VAR_3}. The Wardens collected {VAR_4} denars.";
        internal const string gwp_envoy_outcome_bribed = "{=gwp_envoy_outcome_bribed}Negotiation ended: the warden took {VAR_1} denars privately and closed the case.";
        internal const string gwp_envoy_outcome_duel_called = "{=gwp_envoy_outcome_duel_called}Agreement reached: duel at {VAR_1}.";
        internal const string gwp_envoy_outcome_duel_cancelled = "{=gwp_envoy_outcome_duel_cancelled}Negotiation failed: the duel agreement was cancelled.";
        internal const string gwp_envoy_outcome_duel_lost = "{=gwp_envoy_outcome_duel_lost}Agreement fulfilled: the offender won the duel; case closed.";
        internal const string gwp_envoy_outcome_duel_won = "{=gwp_envoy_outcome_duel_won}Agreement fulfilled: the warden won the duel and collected {VAR_1} denars.";
        internal const string gwp_envoy_outcome_failed = "{=gwp_envoy_outcome_failed}Negotiation failed.";
        internal const string gwp_envoy_outcome_grace = "{=gwp_envoy_outcome_grace}Agreement reached: payment extended.";
        internal const string gwp_envoy_outcome_grace_broke = "{=gwp_envoy_outcome_grace_broke}Negotiation failed: payment was not made by the deadline.";
        internal const string gwp_envoy_outcome_lost = "{=gwp_envoy_outcome_lost}Negotiation failed: the envoy went missing.";
        internal const string gwp_envoy_outcome_paid = "{=gwp_envoy_outcome_paid}Agreement reached: paid {VAR_1} denars; case closed.";
        internal const string gwp_envoy_outcome_paid_share = "{=gwp_envoy_outcome_paid_share}Agreement reached: case closed after a payment of {VAR_1} denars.";
        internal const string gwp_envoy_outcome_refused = "{=gwp_envoy_outcome_refused}Negotiation failed: the offender refused to talk.";
        internal const string gwp_envoy_outcome_surrender = "{=gwp_envoy_outcome_surrender}Agreement reached: the offender surrendered.";
        internal const string gwp_envoy_outcome_talks_failed = "{=gwp_envoy_outcome_talks_failed}Negotiation failed: no agreement.";
        internal const string gwp_envoy_outcome_war = "{=gwp_envoy_outcome_war}Negotiation failed: the factions are at war.";
        internal const string gwp_envoy_party_name = "{=gwp_envoy_party_name}Grey Warden envoy";
        internal const string gwp_envoy_report_header = "{=gwp_envoy_report_header}Envoy report: {VAR_1}";
        internal const string gwp_envoy_report_time = "{=gwp_envoy_report_time}Reported: {VAR_1}";
        internal const string gwp_envoy_report_warden = "{=gwp_envoy_report_warden}Sent by: {VAR_1}";
        internal const string gwp_fa_accept_bribe = "{=gwp_fa_accept_bribe}Hand it over. This conversation did not happen.";
        internal const string gwp_fa_accept_count = "{=gwp_fa_accept_count}Show me the money and goods. We will agree what they cover.";
        internal const string gwp_fa_accept_cunning = "{=gwp_fa_accept_cunning}Half, then. The rest stays against your name.";
        internal const string gwp_fa_accept_deeds = "{=gwp_fa_accept_deeds}Pay for the deed, then. The dead stay on your record.";
        internal const string gwp_fa_accept_duel = "{=gwp_fa_accept_duel}Draw, then. Let us settle it between us.";
        internal const string gwp_fa_accept_empty = "{=gwp_fa_accept_empty}I will report that you could not pay. Your debt remains.";
        internal const string gwp_fa_accept_grace = "{=gwp_fa_accept_grace}Three days, once only. I will return for payment.";
        internal const string gwp_fa_accept_haggle = "{=gwp_fa_accept_haggle}Seven tenths, then. I will have to account for the shortfall.";
        internal const string gwp_fa_accept_payfull = "{=gwp_fa_accept_payfull}The full sum. Hand it over.";
        internal const string gwp_fa_accept_rash = "{=gwp_fa_accept_rash}Most of it will do. The remainder stays on the account.";
        internal const string gwp_fa_accept_surrender = "{=gwp_fa_accept_surrender}Then ride with me. Your men can find their own way.";
        internal const string gwp_fa_arg_authority_charm = "{=gwp_fa_arg_authority_charm}Hired or sworn, the dead are still dead and someone had to come.";
        internal const string gwp_fa_arg_authority_lead = "{=gwp_fa_arg_authority_lead}The Wardens sent me to deal with this. I am conveying their demand.";
        internal const string gwp_fa_arg_authority_rogue = "{=gwp_fa_arg_authority_rogue}They hired me because they were tired of asking politely.";
        internal const string gwp_fa_arg_authority_trade = "{=gwp_fa_arg_authority_trade}Whether you accept me or not, the Wardens will still demand payment. Settling now saves you trouble.";
        internal const string gwp_fa_arg_consequence_charm = "{=gwp_fa_arg_consequence_charm}Then the next grey rider is not here to talk, and neither of us wants that.";
        internal const string gwp_fa_arg_consequence_lead = "{=gwp_fa_arg_consequence_lead}My departure would not make the Wardens drop this. We need an answer today.";
        internal const string gwp_fa_arg_consequence_rogue = "{=gwp_fa_arg_consequence_rogue}You can wager that I cannot take you. You cannot choose how many Wardens come next time.";
        internal const string gwp_fa_arg_consequence_trade = "{=gwp_fa_arg_consequence_trade}The debt remains until it is settled. Waiting does not make it disappear.";
        internal const string gwp_fa_arg_denial_charm = "{=gwp_fa_arg_denial_charm}Nobody in that village could tell your hand from theirs.";
        internal const string gwp_fa_arg_denial_lead = "{=gwp_fa_arg_denial_lead}They are your men. That is what the word means.";
        internal const string gwp_fa_arg_denial_rogue = "{=gwp_fa_arg_denial_rogue}They acted under your banner. Blame your men, and the Wardens will still come for you.";
        internal const string gwp_fa_arg_denial_trade = "{=gwp_fa_arg_denial_trade}They are your men. Pay for the harm first; how you recover it from them is your affair.";
        internal const string gwp_fa_arg_price_charm = "{=gwp_fa_arg_price_charm}The victims have already borne the loss. Do not add another fight to it.";
        internal const string gwp_fa_arg_price_lead = "{=gwp_fa_arg_price_lead}This is the fine the Wardens demand. I was sent to enforce it, not invent a price.";
        internal const string gwp_fa_arg_price_rogue = "{=gwp_fa_arg_price_rogue}It is the cheap answer. You are looking at the expensive one.";
        internal const string gwp_fa_arg_price_trade = "{=gwp_fa_arg_price_trade}The damage and the people harmed both need answering for. This sum covers more than this one encounter.";
        internal const string gwp_fa_arg_record_charm = "{=gwp_fa_arg_record_charm}They took you once and let you ride. Few orders would have.";
        internal const string gwp_fa_arg_record_lead = "{=gwp_fa_arg_record_lead}It goes until you stop giving them cause. That part is yours.";
        internal const string gwp_fa_arg_record_rogue = "{=gwp_fa_arg_record_rogue}You know how an arrest ends. Do you want to go through that again?";
        internal const string gwp_fa_arg_record_trade = "{=gwp_fa_arg_record_trade}Pay what is assessed now. Any future offence will have its own reckoning.";
        internal const string gwp_fa_arg_tally_charm = "{=gwp_fa_arg_tally_charm}Each one had people in it. They were months apart for you, not for them.";
        internal const string gwp_fa_arg_tally_lead = "{=gwp_fa_arg_tally_lead}Time passing does not remove your responsibility. The Wardens hold you answerable for all of it.";
        internal const string gwp_fa_arg_tally_rogue = "{=gwp_fa_arg_tally_rogue}If you wanted them charged separately you should have been caught sooner.";
        internal const string gwp_fa_arg_tally_trade = "{=gwp_fa_arg_tally_trade}Settle these offences together today and spare your party repeated interruptions over them.";
        internal const string gwp_fa_arg_under_charm = "{=gwp_fa_arg_under_charm}Then let us avoid another bad outcome. Settle this today so everyone can go home.";
        internal const string gwp_fa_arg_under_lead = "{=gwp_fa_arg_under_lead}My conduct is a separate matter. You must answer to the Wardens for this.";
        internal const string gwp_fa_arg_under_rogue = "{=gwp_fa_arg_under_rogue}That gives me all the more reason not to return empty-handed. Think carefully.";
        internal const string gwp_fa_arg_under_trade = "{=gwp_fa_arg_under_trade}Talking about me saves you not one denar. It does not reduce what you owe.";
        internal const string gwp_fa_arg_war_charm = "{=gwp_fa_arg_war_charm}Carters and guards. Not one of them was holding your line.";
        internal const string gwp_fa_arg_war_lead = "{=gwp_fa_arg_war_lead}Your war does not reach the drivers. The Wardens' law does.";
        internal const string gwp_fa_arg_war_rogue = "{=gwp_fa_arg_war_rogue}Call it war if it helps. The Wardens call it a caravan and a body count.";
        internal const string gwp_fa_arg_war_trade = "{=gwp_fa_arg_war_trade}Wars end. Accounts do not, until someone pays them.";
        internal const string gwp_fa_charge_cooled = "{=gwp_fa_charge_cooled}Let us take up that charge again.";
        internal const string gwp_fa_collection_cancel = "{=gwp_fa_collection_cancel}No payment has changed hands. What do you intend to do?";
        internal const string gwp_fa_collection_empty = "{=gwp_fa_collection_empty}See for yourself. There is no money or property left to give you.";
        internal const string gwp_fa_collection_paid = "{=gwp_fa_collection_paid}The money is counted. We are done here.";
        internal const string gwp_fa_count_money = "{=gwp_fa_count_money}Here are the money and goods. Choose what you will take.";
        internal const string gwp_fa_counter_offer = "{=gwp_fa_counter_offer}Those terms will not do. Let us discuss the full fine.";
        internal const string gwp_fa_critical_rebuff = "{=gwp_fa_critical_rebuff}Enough. I will hear no more of this.";
        internal const string gwp_fa_desire_bribe = "{=gwp_fa_desire_bribe}Property worth {GWP_BRIBE_AMOUNT} denars, for you alone. What you tell the Wardens is your affair.";
        internal const string gwp_fa_desire_cautious = "{=gwp_fa_desire_cautious}Keep your weapons lowered. I will pay what you ask; there need be no battle.";
        internal const string gwp_fa_desire_cunning = "{=gwp_fa_desire_cunning}Half. That is what the baggage carries, and that is what you are getting.";
        internal const string gwp_fa_desire_deeds = "{=gwp_fa_desire_deeds}I will pay two fifths. The men I blame will answer to me with their lives.";
        internal const string gwp_fa_desire_done_line = "{=gwp_fa_desire_done_line}Then we understand each other.";
        internal const string gwp_fa_desire_duel = "{=gwp_fa_desire_duel}Fight me alone. If you win, I pay the fine; if I win, you collect nothing.";
        internal const string gwp_fa_desire_generous = "{=gwp_fa_desire_generous}I can spare the silver. Take the full amount and see that this account is settled.";
        internal const string gwp_fa_desire_grace = "{=gwp_fa_desire_grace}Give me three days to raise the money. Come back then and I will answer for the payment.";
        internal const string gwp_fa_desire_haggle = "{=gwp_fa_desire_haggle}I will give you seven tenths of the fine. That is my offer.";
        internal const string gwp_fa_desire_merciful = "{=gwp_fa_desire_merciful}Enough people have suffered. Take the full fine, and let there be no more bloodshed.";
        internal const string gwp_fa_desire_payfull = "{=gwp_fa_desire_payfull}Very well. The full sum, and we are finished here.";
        internal const string gwp_fa_desire_rash = "{=gwp_fa_desire_rash}Take four fifths of the fine and let us finish this.";
        internal const string gwp_fa_desire_surrender = "{=gwp_fa_desire_surrender}That silver is my men's wages. Take me instead - I ride with you, and they go home.";
        internal const string gwp_fa_grace_wait = "{=gwp_fa_grace_wait}Then I will come back on the day we named.";
        internal const string gwp_fa_hear_charge = "{=gwp_fa_hear_charge}I have heard the charge. First tell me why I should answer to you.";
        internal const string gwp_fa_l1_done = "{=gwp_fa_l1_done}...Very well. I answer to the charge. The question is how.";
        internal const string gwp_fa_l1_failed = "{=gwp_fa_l1_failed}Enough. Your order has no claim on me, and neither do you.";
        internal const string gwp_fa_l1_lost = "{=gwp_fa_l1_lost}I reject this demand from the Wardens. If you insist on force, draw.";
        internal const string gwp_fa_l2_done = "{=gwp_fa_l2_done}...The full sum, then. Have it your way.";
        internal const string gwp_fa_l2_failed = "{=gwp_fa_l2_failed}No. I have told you how this will go.";
        internal const string gwp_fa_leave_it = "{=gwp_fa_leave_it}Ride on, then. This is not finished.";
        internal const string gwp_fa_open_known = "{=gwp_fa_open_known}The Wardens again. I remember the last time.";
        internal const string gwp_fa_open_known_variant_1 = "{=gwp_fa_open_known_variant_1}I have not forgotten being taken by your people. What do you want this time?";
        internal const string gwp_fa_open_known_variant_2 = "{=gwp_fa_open_known_variant_2}Stopping me again? What do the Wardens want now?";
        internal const string gwp_fa_open_plain = "{=gwp_fa_open_plain}The Wardens. What do you want with me?";
        internal const string gwp_fa_open_respected = "{=gwp_fa_open_respected}I know the grey. Speak, and speak plainly.";
        internal const string gwp_fa_open_respected_known = "{=gwp_fa_open_respected_known}You again. Or your order, at least. What is it this time?";
        internal const string gwp_fa_open_respected_known_variant_1 = "{=gwp_fa_open_respected_known_variant_1}You. My last meeting with the Wardens was no pleasure. What is it now?";
        internal const string gwp_fa_open_respected_known_variant_2 = "{=gwp_fa_open_respected_known_variant_2}The Wardens want me again? Speak. I am listening.";
        internal const string gwp_fa_open_respected_variant_1 = "{=gwp_fa_open_respected_variant_1}I have heard of you. State your business.";
        internal const string gwp_fa_open_respected_variant_2 = "{=gwp_fa_open_respected_variant_2}If the Wardens sent you, there must be business to discuss. Go on.";
        internal const string gwp_fa_open_under_charge = "{=gwp_fa_open_under_charge}You work for the Wardens? Tell me what you want.";
        internal const string gwp_fa_open_under_charge_variant_1 = "{=gwp_fa_open_under_charge_variant_1}You work for the Wardens now? That is new. What do you want?";
        internal const string gwp_fa_open_under_charge_variant_2 = "{=gwp_fa_open_under_charge_variant_2}I have heard of you. Tell me what the Wardens sent you for.";
        internal const string gwp_fa_rebuff_cold = "{=gwp_fa_rebuff_cold}Nothing has changed since we last spoke.";
        internal const string gwp_fa_rebuff_fierce = "{=gwp_fa_rebuff_fierce}We settled this once already. Press me again and it will not be with words.";
        internal const string gwp_fa_rebuff_plain = "{=gwp_fa_rebuff_plain}We have spoken about this. My answer stands.";
        internal const string gwp_fa_rebuff_soft = "{=gwp_fa_rebuff_soft}Please. We have been over it once already. Let it rest.";
        internal const string gwp_fa_rebuff_tight = "{=gwp_fa_rebuff_tight}You have had your talk out of me. Talk is not free, and you have spent it.";
        internal const string gwp_fa_rebuff_upright = "{=gwp_fa_rebuff_upright}You have my answer. I do not give a man two.";
        internal const string gwp_fa_refuse_strength = "{=gwp_fa_refuse_strength}I will not accept this demand. We have nothing to discuss.";
        internal const string gwp_fa_request_terms = "{=gwp_fa_request_terms}Then tell me how you propose to settle this.";
        internal const string gwp_fa_retry_authority = "{=gwp_fa_retry_authority}That is not enough for me to accept your authority. Have you another reason?";
        internal const string gwp_fa_retry_payment = "{=gwp_fa_retry_payment}I still stand by my terms. Have you another proposal?";
        internal const string gwp_fa_take_anyway = "{=gwp_fa_take_anyway}Keep your silver. I am taking you in.";
        internal const string gwp_fa_take_by_force = "{=gwp_fa_take_by_force}I will enforce the warrant by force.";
        internal const string gwp_fa_task_authority = "{=gwp_fa_task_authority}You are not my liege and you are not a Warden. You are a man they hired.";
        internal const string gwp_fa_task_authority_variant_1 = "{=gwp_fa_task_authority_variant_1}The Wardens may have a say, but that does not put you in command of me.";
        internal const string gwp_fa_task_authority_variant_2 = "{=gwp_fa_task_authority_variant_2}You are running an errand for the Wardens. Why should I answer to you?";
        internal const string gwp_fa_task_consequence = "{=gwp_fa_task_consequence}And if I simply refuse to pay? What can you do about it?";
        internal const string gwp_fa_task_consequence_variant_1 = "{=gwp_fa_task_consequence_variant_1}Suppose I refuse to pay today. What will you do?";
        internal const string gwp_fa_task_consequence_variant_2 = "{=gwp_fa_task_consequence_variant_2}I will take my men and ride on. Will the Wardens follow me forever?";
        internal const string gwp_fa_task_denial = "{=gwp_fa_task_denial}My men did that. I did not give the order, and I will not pay for their appetite.";
        internal const string gwp_fa_task_denial_variant_1 = "{=gwp_fa_task_denial_variant_1}Ask my soldiers what they did. I gave no such order.";
        internal const string gwp_fa_task_denial_variant_2 = "{=gwp_fa_task_denial_variant_2}Why should I bear all the blame for what my men did?";
        internal const string gwp_fa_task_final = "{=gwp_fa_task_final}You have run out of words, Warden.";
        internal const string gwp_fa_task_later = "{=gwp_fa_task_later}I will hear no more arguments about this warrant.";
        internal const string gwp_fa_task_price = "{=gwp_fa_task_price}And that number - where did it come from? You say it as if it fell from the sky.";
        internal const string gwp_fa_task_price_variant_1 = "{=gwp_fa_task_price_variant_1}That much? What gives the Wardens cause to demand that sum?";
        internal const string gwp_fa_task_price_variant_2 = "{=gwp_fa_task_price_variant_2}You ask for a great deal of money. You owe me an explanation.";
        internal const string gwp_fa_task_rebuff = "{=gwp_fa_task_rebuff}That is no answer.";
        internal const string gwp_fa_task_record = "{=gwp_fa_task_record}Your order has had me once already. Is this how it goes now - forever?";
        internal const string gwp_fa_task_record_variant_1 = "{=gwp_fa_task_record_variant_1}The Wardens already took me once. Was that not enough?";
        internal const string gwp_fa_task_record_variant_2 = "{=gwp_fa_task_record_variant_2}The Wardens again. Must your people follow wherever I go?";
        internal const string gwp_fa_task_tally = "{=gwp_fa_task_tally}You are charging me for things I did months apart, as if they were one crime.";
        internal const string gwp_fa_task_tally_variant_1 = "{=gwp_fa_task_tally_variant_1}You mean to pursue the older offences too? How far back will you go?";
        internal const string gwp_fa_task_tally_variant_2 = "{=gwp_fa_task_tally_variant_2}Those incidents were long apart. Now you bring them all to me at once?";
        internal const string gwp_fa_task_under_charge = "{=gwp_fa_task_under_charge}Your reputation is scarcely better than mine. Now you lecture me for the Wardens?";
        internal const string gwp_fa_task_under_charge_variant_1 = "{=gwp_fa_task_under_charge_variant_1}Your own reputation is hardly spotless. Now you lecture me?";
        internal const string gwp_fa_task_under_charge_variant_2 = "{=gwp_fa_task_under_charge_variant_2}I might listen to someone else. You should put your own affairs right first.";
        internal const string gwp_fa_task_war = "{=gwp_fa_task_war}There is a war on. Taking an enemy's goods is not a crime, it is the work.";
