        internal const string gwp_voice_betray_cold_0 = "{=gwp_voice_betray_cold_0}So payment was not the end. I gave your word too much credit.";
        internal const string gwp_voice_betray_cold_1 = "{=gwp_voice_betray_cold_1}My money in your purse and me in your prison cart? Quite a bargain.";
        internal const string gwp_voice_betray_fierce_0 = "{=gwp_voice_betray_fierce_0}You take my money and turn on me? Draw your sword!";
        internal const string gwp_voice_betray_fierce_1 = "{=gwp_voice_betray_fierce_1}I did not pay out of fear! Now you will learn that.";
        internal const string gwp_voice_betray_plain_0 = "{=gwp_voice_betray_plain_0}Wait, I already paid you! How can you turn on me now?";
        internal const string gwp_voice_betray_plain_1 = "{=gwp_voice_betray_plain_1}That was not our agreement! You have the money. What more do you want?";
        internal const string gwp_voice_betray_soft_0 = "{=gwp_voice_betray_soft_0}I paid so everyone could leave safely. Will you not even allow that?";
        internal const string gwp_voice_betray_soft_1 = "{=gwp_voice_betray_soft_1}You have the money. Why force these people to fight as well?";
        internal const string gwp_voice_betray_tight_0 = "{=gwp_voice_betray_tight_0}Give that money back! Paid and arrested, is that your trade?";
        internal const string gwp_voice_betray_tight_1 = "{=gwp_voice_betray_tight_1}I counted every coin into your hands, and now it means nothing?";
        internal const string gwp_voice_betray_upright_0 = "{=gwp_voice_betray_upright_0}You took the money and now break our agreement? Everyone heard it!";
        internal const string gwp_voice_betray_upright_1 = "{=gwp_voice_betray_upright_1}I paid as agreed. Is this how you serve the Wardens?";
        internal const string gwp_voice_demand_bribethewarden_alt = "{=gwp_voice_demand_bribethewarden_alt}This is worth {GWP_BRIBE_AMOUNT} denars to you. Take it and let our discussion end here.";
        internal const string gwp_voice_demand_cunninghalf_alt = "{=gwp_voice_demand_cunninghalf_alt}I cannot raise that sum. Half is all there is. Take it if you want it.";
        internal const string gwp_voice_demand_deedsonly_alt = "{=gwp_voice_demand_deedsonly_alt}Two fifths is all I will pay. I will kill the men I blame myself.";
        internal const string gwp_voice_demand_demandduel_alt = "{=gwp_voice_demand_demandduel_alt}Just you and me. You win, I pay the fine. I win, you leave empty-handed.";
        internal const string gwp_voice_demand_haggledown_alt = "{=gwp_voice_demand_haggledown_alt}Seven tenths is plenty. Think carefully about that offer.";
        internal const string gwp_voice_demand_payforpeace_alt = "{=gwp_voice_demand_payforpeace_alt}Enough people have suffered. I will pay in full; leave the others out of it.";
        internal const string gwp_voice_demand_paygenerously_alt = "{=gwp_voice_demand_paygenerously_alt}I can afford it. Take the whole sum and settle the account.";
        internal const string gwp_voice_demand_payinfull_alt = "{=gwp_voice_demand_payinfull_alt}I will pay the assessed sum. Let us settle this.";
        internal const string gwp_voice_demand_paytoavoidbattle_alt = "{=gwp_voice_demand_paytoavoidbattle_alt}Tell your men to hold. I will pay in full; nobody needs to die here.";
        internal const string gwp_voice_demand_rashmost_alt = "{=gwp_voice_demand_rashmost_alt}Four fifths. Take it. Spare me the argument over the rest.";
        internal const string gwp_voice_demand_surrenderself_alt = "{=gwp_voice_demand_surrenderself_alt}The money must feed these men. If you need a prisoner, take me alone.";
        internal const string gwp_voice_done1_alt = "{=gwp_voice_done1_alt}All right, I accept the charge. We still have to agree on how to settle it.";
        internal const string gwp_voice_done2_alt = "{=gwp_voice_done2_alt}All right, the sum you named. No further conditions.";
        internal const string gwp_voice_fight_cold_0 = "{=gwp_voice_fight_cold_0}There is nothing left to reckon. Form up.";
        internal const string gwp_voice_fight_cold_1 = "{=gwp_voice_fight_cold_1}You chose this course. I hope you counted the cost.";
        internal const string gwp_voice_fight_fierce_0 = "{=gwp_voice_fight_fierce_0}Good! We could have spared ourselves the speeches.";
        internal const string gwp_voice_fight_fierce_1 = "{=gwp_voice_fight_fierce_1}Come, then. Let us see if you can!";
        internal const string gwp_voice_fight_plain_0 = "{=gwp_voice_fight_plain_0}Then there is nothing left to say. Draw.";
        internal const string gwp_voice_fight_plain_1 = "{=gwp_voice_fight_plain_1}I will not hold out my hands for your ropes.";
        internal const string gwp_voice_fight_soft_0 = "{=gwp_voice_fight_soft_0}Must this end in blood? Then I have to defend my people.";
        internal const string gwp_voice_fight_soft_1 = "{=gwp_voice_fight_soft_1}Stand back, away from us. It seems there is no avoiding this.";
        internal const string gwp_voice_fight_tight_0 = "{=gwp_voice_fight_tight_0}Cannot take the money, so you take me? Try it.";
        internal const string gwp_voice_fight_tight_1 = "{=gwp_voice_fight_tight_1}You want to hand me over? It will not be easy.";
        internal const string gwp_voice_fight_upright_0 = "{=gwp_voice_fight_upright_0}Let everyone here see who draws first.";
        internal const string gwp_voice_fight_upright_1 = "{=gwp_voice_fight_upright_1}I will not submit. Come and take me.";
