        internal const string gwp_voice_lost1_alt = "{=gwp_voice_lost1_alt}You still have not given me a reason to submit. Stop circling the matter.";
        internal const string gwp_voice_lost2_alt = "{=gwp_voice_lost2_alt}I will not yield on that. My offer still stands.";
        internal const string gwp_voice_open_cold_0 = "{=gwp_voice_open_cold_0}You did not chase me down to ask directions. Speak.";
        internal const string gwp_voice_open_cold_1 = "{=gwp_voice_open_cold_1}The Wardens want me? Tell me the business first.";
        internal const string gwp_voice_open_fierce_0 = "{=gwp_voice_open_fierce_0}You had better have a reason for blocking my road.";
        internal const string gwp_voice_open_fierce_1 = "{=gwp_voice_open_fierce_1}I can see your banner. What do you want?";
        internal const string gwp_voice_open_plain_0 = "{=gwp_voice_open_plain_0}You work for the Wardens? What is this about?";
        internal const string gwp_voice_open_plain_1 = "{=gwp_voice_open_plain_1}Wait. Did you say the Wardens sent you?";
        internal const string gwp_voice_open_soft_0 = "{=gwp_voice_open_soft_0}Speak here. There is no need to alarm the others.";
        internal const string gwp_voice_open_soft_1 = "{=gwp_voice_open_soft_1}The Wardens... Who has suffered this time?";
        internal const string gwp_voice_open_tight_0 = "{=gwp_voice_open_tight_0}Say your piece. I have promised you nothing.";
        internal const string gwp_voice_open_tight_1 = "{=gwp_voice_open_tight_1}A visit from your people is seldom cheap.";
        internal const string gwp_voice_open_upright_0 = "{=gwp_voice_open_upright_0}Show me the warrant. I will answer a proper charge.";
        internal const string gwp_voice_open_upright_1 = "{=gwp_voice_open_upright_1}If you speak for the Wardens, state your business clearly.";
        internal const string gwp_voice_paid_0 = "{=gwp_voice_paid_0}We counted the money together. Why are you back?";
        internal const string gwp_voice_paid_1 = "{=gwp_voice_paid_1}I have paid you. What remains to discuss?";
        internal const string gwp_voice_plead_cold_0 = "{=gwp_voice_plead_cold_0}You have named a sum I cannot meet. Wages, feed, remounts - look at the column and tell me where it hides.";
        internal const string gwp_voice_plead_cold_1 = "{=gwp_voice_plead_cold_1}The figure is beyond me. I can show you the accounts if you doubt it.";
        internal const string gwp_voice_plead_cold_2 = "{=gwp_voice_plead_cold_2}What you ask does not exist in my purse. That is simply the arithmetic.";
        internal const string gwp_voice_plead_fierce_0 = "{=gwp_voice_plead_fierce_0}I have no such money, and I will not pretend otherwise.";
        internal const string gwp_voice_plead_fierce_1 = "{=gwp_voice_plead_fierce_1}Ask for what I have, not for what I do not.";
        internal const string gwp_voice_plead_plain_0 = "{=gwp_voice_plead_plain_0}That sum? I do not carry it. Search the baggage if you like.";
        internal const string gwp_voice_plead_plain_1 = "{=gwp_voice_plead_plain_1}I cannot raise that. Not today, not from what I have here.";
        internal const string gwp_voice_plead_soft_0 = "{=gwp_voice_plead_soft_0}I have men to feed before I have coin for you. There is nothing left.";
        internal const string gwp_voice_plead_soft_1 = "{=gwp_voice_plead_soft_1}Do not take what these people still need. I cannot meet it.";
        internal const string gwp_voice_plead_tight_0 = "{=gwp_voice_plead_tight_0}I am not a rich man, whatever your ledger says. You will not find it on me.";
        internal const string gwp_voice_plead_tight_1 = "{=gwp_voice_plead_tight_1}Search me if you like. There is nothing like that sum here.";
        internal const string gwp_voice_plead_tight_2 = "{=gwp_voice_plead_tight_2}You have been told wrong about my means. I cannot pay it.";
        internal const string gwp_voice_plead_upright_0 = "{=gwp_voice_plead_upright_0}I will not promise what I cannot pay. That sum is beyond me.";
        internal const string gwp_voice_plead_upright_1 = "{=gwp_voice_plead_upright_1}I would pay it if I had it. I do not.";
        internal const string gwp_voice_refuse_alt = "{=gwp_voice_refuse_alt}You want me to accept your authority? No. Stand aside.";
        internal const string gwp_voice_resist_cold_0 = "{=gwp_voice_resist_cold_0}I have counted your column and I have counted mine. No.";
        internal const string gwp_voice_resist_cold_1 = "{=gwp_voice_resist_cold_1}The odds do not favour you enough. My answer is no.";
        internal const string gwp_voice_resist_cold_2 = "{=gwp_voice_resist_cold_2}No. You may test that answer if you wish.";
        internal const string gwp_voice_resist_fierce_0 = "{=gwp_voice_resist_fierce_0}I have never bought my way out of anything. Draw.";
        internal const string gwp_voice_resist_fierce_1 = "{=gwp_voice_resist_fierce_1}You will take nothing from me while I stand. Come on, then.";
        internal const string gwp_voice_resist_fierce_2 = "{=gwp_voice_resist_fierce_2}Enough talk. Let the swords settle it.";
        internal const string gwp_voice_resist_plain_0 = "{=gwp_voice_resist_plain_0}No. Come and take it, if you can.";
        internal const string gwp_voice_resist_plain_1 = "{=gwp_voice_resist_plain_1}My answer is no. Do as you must.";
        internal const string gwp_voice_resist_scorn_0 = "{=gwp_voice_resist_scorn_0}You are under your own charge and you come to collect mine? Draw.";
        internal const string gwp_voice_resist_scorn_1 = "{=gwp_voice_resist_scorn_1}A wanted man collecting fines. I will not answer to you.";
        internal const string gwp_voice_resist_scorn_2 = "{=gwp_voice_resist_scorn_2}Put your own name right before you read mine off a list.";
        internal const string gwp_voice_resist_soft_0 = "{=gwp_voice_resist_soft_0}I cannot give you what my people still need. I will not.";
        internal const string gwp_voice_resist_soft_1 = "{=gwp_voice_resist_soft_1}I am sorry it comes to this, but my answer is no.";
        internal const string gwp_voice_resist_tight_0 = "{=gwp_voice_resist_tight_0}You will not have a denar of it. Not one.";
        internal const string gwp_voice_resist_tight_1 = "{=gwp_voice_resist_tight_1}I would sooner bleed than pay that. Try me.";
        internal const string gwp_voice_resist_tight_2 = "{=gwp_voice_resist_tight_2}Not a coin. Take it off my body if you can.";
        internal const string gwp_voice_resist_upright_0 = "{=gwp_voice_resist_upright_0}I will not pay for a charge I do not accept. Do what you came to do.";
        internal const string gwp_voice_resist_upright_1 = "{=gwp_voice_resist_upright_1}Bring me before someone with the standing to judge it. Until then, no.";
        internal const string gwp_voice_submit_cold_0 = "{=gwp_voice_submit_cold_0}Cheaper than the alternative. That is the only reason, and we both know it.";
        internal const string gwp_voice_submit_cold_1 = "{=gwp_voice_submit_cold_1}The sum is smaller than the trouble. Take it.";
        internal const string gwp_voice_submit_cold_2 = "{=gwp_voice_submit_cold_2}I have weighed it. You win this column. Count your money.";
        internal const string gwp_voice_submit_fierce_0 = "{=gwp_voice_submit_fierce_0}Fine. Money, then. Do not mistake it for fear.";
        internal const string gwp_voice_submit_fierce_1 = "{=gwp_voice_submit_fierce_1}Take your coin. It settles nothing between us.";
        internal const string gwp_voice_submit_fierce_2 = "{=gwp_voice_submit_fierce_2}Here, and let that be the end of your talking.";
        internal const string gwp_voice_submit_plain_0 = "{=gwp_voice_submit_plain_0}Here. Count it, and be gone.";
        internal const string gwp_voice_submit_plain_1 = "{=gwp_voice_submit_plain_1}All right. The sum you named, no more.";
        internal const string gwp_voice_submit_plain_2 = "{=gwp_voice_submit_plain_2}Take it. I want no further trouble over this.";
        internal const string gwp_voice_submit_soft_0 = "{=gwp_voice_submit_soft_0}Take it. It buys nothing back, but take it.";
        internal const string gwp_voice_submit_soft_1 = "{=gwp_voice_submit_soft_1}If this closes the matter for them, then take it.";
        internal const string gwp_voice_submit_soft_2 = "{=gwp_voice_submit_soft_2}Here. I would rather it went to them than stayed with me.";
        internal const string gwp_voice_submit_tight_0 = "{=gwp_voice_submit_tight_0}Every coin of it. I hope your order chokes on the counting.";
        internal const string gwp_voice_submit_tight_1 = "{=gwp_voice_submit_tight_1}There. Count it twice, you will not find a coin short.";
        internal const string gwp_voice_submit_tight_2 = "{=gwp_voice_submit_tight_2}Take it and be quick. Every moment of this costs me more.";
        internal const string gwp_voice_submit_upright_0 = "{=gwp_voice_submit_upright_0}The charge is fair. Take it, and let it be written that I paid it standing.";
        internal const string gwp_voice_submit_upright_1 = "{=gwp_voice_submit_upright_1}I will not argue a debt I owe. Count it.";
        internal const string gwp_voice_submit_upright_2 = "{=gwp_voice_submit_upright_2}Then it is owed, and I pay what is owed. Here.";
        internal const string gwp_voice_success_cold_0 = "{=gwp_voice_success_cold_0}That is something I must consider.";
        internal const string gwp_voice_success_cold_1 = "{=gwp_voice_success_cold_1}That does change the reckoning.";
        internal const string gwp_voice_success_fierce_0 = "{=gwp_voice_success_fierce_0}All right. I hear you.";
        internal const string gwp_voice_success_fierce_1 = "{=gwp_voice_success_fierce_1}That argument carries some weight.";
        internal const string gwp_voice_success_plain_0 = "{=gwp_voice_success_plain_0}That is true.";
        internal const string gwp_voice_success_plain_1 = "{=gwp_voice_success_plain_1}You have persuaded me on that point.";
        internal const string gwp_voice_success_soft_0 = "{=gwp_voice_success_soft_0}I cannot ignore the people you speak of.";
        internal const string gwp_voice_success_soft_1 = "{=gwp_voice_success_soft_1}Yes... I should give that more thought.";
        internal const string gwp_voice_success_tight_0 = "{=gwp_voice_success_tight_0}As you put it, there is something in it for me.";
        internal const string gwp_voice_success_tight_1 = "{=gwp_voice_success_tight_1}Those figures do make some sense.";
        internal const string gwp_voice_success_upright_0 = "{=gwp_voice_success_upright_0}That is a fair point. I accept it.";
        internal const string gwp_voice_success_upright_1 = "{=gwp_voice_success_upright_1}I cannot dispute that point.";
        internal const string gwp_warden_marry_ask = "{=gwp_warden_marry_ask}Be my wife.";
        internal const string gwp_warden_marry_yes = "{=gwp_warden_marry_yes}Then it is settled. I am yours, and you are mine.";
        internal const string gwp_warden_mediation_ask = "{=gwp_warden_mediation_ask}The fighting I did on your account has left me at war. Speak for me.";
        internal const string gwp_warden_mediation_done = "{=gwp_warden_mediation_done}Consider it carried. Word goes out today, and the quarrels you took up for us are closed.";
        internal const string gwp_warden_mediation_moot = "{=gwp_warden_mediation_moot}There is nothing left for us to carry. Whatever you took up on our account is already settled.";
        internal const string gwp_warden_mediation_owed = "{=gwp_warden_mediation_owed}This war began when you fought for the Wardens. You may ask them to mediate.";
    }
}
